/**
 * Toast.Card: one toast in the viewport, with its timer, its dismissal and its exit.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/toast.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, onCleanup, type JSX } from 'solid-js'

import {
  Icon,
  TOAST_TONE_ICON,
  claimSlot,
  classes,
  createCell,
  createDerived,
  elementRef,
  removeToast,
  scope,
  toast,
  watchEffect,
  type ToastRecord,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/overlays/toast.module.css'
import Button from '../controls/Button'

export interface ToastCardProps {
  record: ToastRecord
  /**
   * The close button’s accessible name.
   */
  dismissLabel: string
  /**
   * The reader is on the list, so the timer waits.
   */
  paused: boolean
}

/** Toast.Card: one toast in the viewport, with its timer, its dismissal and its exit. */
export default function ToastCard(given: ToastCardProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    const swipe = createCell('')
    const tracking = createCell(false)
    const startX = createCell(0)
    const deltaX = createCell(0)
    const card = elementRef<HTMLElement>()
    const icon = createDerived(() =>
      props.record.tone === 'neutral' ? null : TOAST_TONE_ICON[props.record.tone],
    )
    const dismissible = createDerived(() => props.record.dismissible !== false)
    const dismiss = createDerived(() => (): void => {
      if (dismissible.value) toast.dismiss(props.record.id)
    })
    const act = createDerived(() => (): void => {
      props.record.action?.onClick()
      toast.dismiss(props.record.id)
    })
    const press = createDerived(() => (event: PointerEvent): void => {
      if (
        !dismissible.value ||
        event.button !== 0 ||
        (event.target as Element).closest('button') !== null
      )
        return
      tracking.value = true
      startX.value = event.clientX
      deltaX.value = 0
    })
    const drag = createDerived(() => (event: PointerEvent): void => {
      if (!tracking.value) return
      deltaX.value = Math.max(0, event.clientX - startX.value)
      if (deltaX.value > 0) swipe.value = 'move'
    })
    const lift = createDerived(() => (): void => {
      if (!tracking.value) return
      tracking.value = false
      if (swipe.value !== 'move') return
      if (deltaX.value > 50) {
        swipe.value = 'end'
        dismiss.value()
      } else {
        swipe.value = 'cancel'
        deltaX.value = 0
      }
    })
    const present = usePresence(
      () => props.record.closing !== true,
      () => card.value,
      'toast.enter',
    )
    const effect1 = () => {
      void (present() || removeToast(props.record.id))
    }
    watchEffect(
      createMemo(() => present()),
      effect1,
      false,
    )
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const timer = setTimeout(
        () => {
          void (
            !props.paused &&
            props.record.closing !== true &&
            dismissible.value &&
            Number.isFinite(props.record.durationMs) &&
            toast.dismiss(props.record.id)
          )
        },
        Number.isFinite(props.record.durationMs) ? props.record.durationMs : 0,
      )
      release2 = () => clearTimeout(timer)
    }
    watchEffect(
      createMemo(() => [props.record.revision, props.paused, props.record.closing]),
      effect2,
      true,
    )
    onCleanup(() => release2?.())
    return (
      <li
        class={styles.toast}
        style={{
          '--radix-toast-swipe-move-x': `${deltaX.value}px`,
          '--radix-toast-swipe-end-x': `${deltaX.value}px`,
        }}
        tabindex="0"
        data-tone={props.record.tone}
        data-state={props.record.closing === true ? 'closed' : 'open'}
        data-swipe={swipe.value === '' ? undefined : swipe.value}
        data-swipe-direction="right"
        data-member="toast"
        onkeydown={($event: KeyboardEvent) =>
          $event.key === 'Escape' && ($event.preventDefault(), dismiss.value())
        }
        onpointerdown={($event: PointerEvent) => press.value($event)}
        onpointermove={($event: PointerEvent) => drag.value($event)}
        onpointerup={() => lift.value()}
        onpointercancel={() => lift.value()}
        ref={card.attach}
      >
        {props.record.loading === true ? (
          <span class={classes(styles.tone, styles.wait)} aria-hidden="true">
            <Icon name="loading" />
          </span>
        ) : icon.value !== null ? (
          <span class={styles.tone}>
            <Icon name={icon.value} />
          </span>
        ) : null}
        {/* text */}
        <div class={styles.text}>
          {/* title */}
          <div class={styles.title} data-toast-title={''}>
            {props.record.title}
          </div>
          {props.record.description !== undefined ? (
            <div class={styles.description}>{props.record.description}</div>
          ) : null}
          {props.record.content !== undefined ? (
            <div class={styles.content}>{props.record.content}</div>
          ) : null}
        </div>
        {props.record.action !== undefined ? (
          <div class={styles.action}>
            <Button
              variant="ghost"
              tone={props.record.tone === 'danger' ? 'danger' : 'accent'}
              size="sm"
              label={props.record.action?.label ?? ''}
              onClick={() => act.value()}
            />
          </div>
        ) : null}
        {dismissible.value ? (
          <div class={styles.close}>
            <Button
              variant="ghost"
              tone="neutral"
              size="sm"
              iconOnly={true}
              icon="close"
              label={props.dismissLabel}
              onClick={() => dismiss.value()}
            />
          </div>
        ) : null}
      </li>
    )
  })
}
